    li      x6, 0xA000000000000000   // temp base for ADDI sweep
    addi    x1,  x6, 1
    addi    x2,  x6, 2
    addi    x3,  x6, 3
    addi    x4,  x6, 4
    addi    x7,  x6, 7
    addi    x8,  x6, 8
    addi    x9,  x6, 9
    addi    x10, x6, 10
